-- @seq 213
CREATE FUNCTION public.acct_inventory_adjust(p_item_id uuid, p_qty_change numeric, p_date date, p_reason text, p_unit_cost numeric DEFAULT NULL::numeric, p_offset_account_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_move_type text DEFAULT 'adjustment'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE it acct_items%ROWTYPE; v_off uuid; r record; v_cost numeric; v_move uuid; v_id uuid := gen_random_uuid();
BEGIN
  SELECT * INTO it FROM acct_items WHERE id = p_item_id;
  PERFORM acct_assert_access(it.tenant_id);
  IF it.item_type <> 'inventory' THEN RAISE EXCEPTION 'Only inventory items carry stock'; END IF;
  IF p_qty_change = 0 THEN RETURN NULL; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required for inventory adjustments'; END IF;
  v_off := coalesce(p_offset_account_id, acct__role(it.tenant_id, it.entity_id, 'inventory_adjustments'));
  IF p_qty_change > 0 THEN
    v_cost := round(p_qty_change * coalesce(p_unit_cost, it.last_unit_cost, it.purchase_cost, 0), 2);
    v_move := acct__inv_receive(it.tenant_id, it.entity_id, it.id, p_qty_change, v_cost, p_date, p_move_type, 'adjustment', v_id, NULL, p_reference, p_reason);
  ELSE
    SELECT * INTO r FROM acct__inv_issue(it.tenant_id, it.entity_id, it.id, -p_qty_change, p_date, p_move_type, 'adjustment', v_id, NULL, p_reference, p_reason);
    v_move := r.move_id; v_cost := -r.cost;
  END IF;
  PERFORM acct__inv_post_je(it.tenant_id, it.entity_id, p_date, jsonb_build_array(
            jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', greatest(v_cost,0), 'credit', greatest(-v_cost,0), 'item_id', it.id, 'description', p_reason),
            jsonb_build_object('account_id', v_off, 'credit', greatest(v_cost,0), 'debit', greatest(-v_cost,0), 'item_id', it.id, 'description', p_reason)),
          p_reference, 'Inventory ' || p_move_type || ': ' || it.name, 'invadj:' || v_id, 'adjustment', v_id, ARRAY[v_move]);
  RETURN v_move;
END $$;

-- @seq 214
CREATE FUNCTION public.acct_inventory_opening(p_item_id uuid, p_qty numeric, p_unit_cost numeric, p_as_of date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE it acct_items%ROWTYPE; v_move uuid; v_cost numeric;
BEGIN
  SELECT * INTO it FROM acct_items WHERE id = p_item_id;
  PERFORM acct_assert_access(it.tenant_id);
  IF it.item_type <> 'inventory' THEN RAISE EXCEPTION 'Only inventory items carry stock'; END IF;
  IF EXISTS (SELECT 1 FROM acct_inventory_moves WHERE item_id = p_item_id AND move_type = 'opening' AND reversed_by_move_id IS NULL) THEN
    RAISE EXCEPTION 'Opening stock already entered for %; use an adjustment', it.name; END IF;
  v_cost := round(p_qty * p_unit_cost, 2);
  v_move := acct__inv_receive(it.tenant_id, it.entity_id, it.id, p_qty, v_cost, p_as_of, 'opening', 'acct_items', it.id, NULL, 'OPENING', 'Opening stock');
  RETURN acct__inv_post_je(it.tenant_id, it.entity_id, p_as_of, jsonb_build_array(
           jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', v_cost, 'item_id', it.id, 'description', 'Opening stock ' || it.name),
           jsonb_build_object('account_id', acct_role_account(it.tenant_id, it.entity_id, 'opening_balance_equity'), 'credit', v_cost, 'description', 'Opening stock ' || it.name)),
         'OPENING', 'Opening stock ' || it.name, 'invopen:' || it.id, 'acct_items', it.id, ARRAY[v_move]);
END $$;

-- @seq 215
CREATE FUNCTION public.acct_inventory_tieout(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(account_code text, account_name text, gl_balance numeric, items_value numeric, difference numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  WITH accts AS (SELECT DISTINCT inventory_asset_account_id id FROM acct_items WHERE tenant_id = p_tenant_id AND item_type = 'inventory'
                 UNION SELECT acct_role_account(p_tenant_id, acct_default_entity(p_tenant_id), 'inventory_asset', false)),
       gl AS (SELECT l.account_id, sum(l.debit - l.credit) bal FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
               WHERE e.tenant_id = p_tenant_id AND e.status IN ('posted','reversed') AND e.posting_date <= p_as_of GROUP BY 1),
       sub AS (SELECT i.inventory_asset_account_id account_id, sum(m.total_cost) val FROM acct_inventory_moves m JOIN acct_items i ON i.id = m.item_id
               WHERE m.tenant_id = p_tenant_id AND m.move_date <= p_as_of GROUP BY 1)
  SELECT a.code, a.name, coalesce(gl.bal,0), coalesce(sub.val,0), coalesce(gl.bal,0) - coalesce(sub.val,0)
    FROM accts x JOIN acct_chart_of_accounts a ON a.id = x.id
    LEFT JOIN gl ON gl.account_id = a.id LEFT JOIN sub ON sub.account_id = a.id
   ORDER BY a.code;
END $$;

-- @seq 216
CREATE FUNCTION public.acct_inventory_valuation(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(item_id uuid, sku text, item_name text, inventory_account text, quantity numeric, value numeric, avg_unit_cost numeric, reorder_point numeric, below_reorder boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  SELECT i.id, i.sku, i.name, a.code || ' ' || a.name, coalesce(sum(m.quantity),0), coalesce(sum(m.total_cost),0),
         round(coalesce(sum(m.total_cost),0) / nullif(sum(m.quantity),0), 4), i.reorder_point,
         coalesce(sum(m.quantity),0) <= coalesce(i.reorder_point, -1e18)
    FROM acct_items i JOIN acct_chart_of_accounts a ON a.id = i.inventory_asset_account_id
    LEFT JOIN acct_inventory_moves m ON m.item_id = i.id AND m.move_date <= p_as_of
   WHERE i.tenant_id = p_tenant_id AND i.item_type = 'inventory'
   GROUP BY i.id, i.sku, i.name, a.code, a.name, i.reorder_point
   ORDER BY i.name;
END $$;

-- @seq 227
CREATE FUNCTION public.acct_item_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c acct_item_classifications%ROWTYPE; p record; v_t text;
BEGIN
  SELECT * INTO c FROM acct_item_classifications WHERE id = NEW.classification_id;
  IF NOT FOUND OR c.tenant_id <> NEW.tenant_id THEN RAISE EXCEPTION 'Pick a SKU line for this item'; END IF;
  IF c.level <> 'sku_line' THEN
    RAISE EXCEPTION 'Items attach to a SKU line (department > sub department > service type > SKU line); % is a %', c.name, c.level; END IF;
  SELECT * INTO p FROM acct_item_class_path(c.id);
  NEW.entity_id := coalesce(NEW.entity_id, acct_default_entity(NEW.tenant_id));
  -- inherit defaults from the hierarchy, then from company roles
  NEW.income_account_id := coalesce(NEW.income_account_id, NEW.category_account_id, p.income_account_id,
                                    CASE WHEN NEW.is_sold AND NEW.item_type NOT IN ('gift_card','discount') THEN acct_role_account(NEW.tenant_id, NEW.entity_id, 'default_income', false) END);
  IF NEW.item_type = 'gift_card' THEN NEW.income_account_id := coalesce(NEW.income_account_id, acct_role_account(NEW.tenant_id, NEW.entity_id, 'gift_card_liability')); NEW.taxable := false; NEW.tax_category := 'gift_card'; END IF;
  IF NEW.item_type = 'discount' THEN NEW.income_account_id := coalesce(NEW.income_account_id, acct_role_account(NEW.tenant_id, NEW.entity_id, 'discounts_given')); END IF;
  NEW.tax_category := coalesce(NEW.tax_category, p.tax_category);
  IF NEW.item_type = 'inventory' THEN
    NEW.is_purchased := true;
    NEW.inventory_asset_account_id := coalesce(NEW.inventory_asset_account_id, p.asset_account_id, acct_role_account(NEW.tenant_id, NEW.entity_id, 'inventory_asset'));
    NEW.cogs_account_id := coalesce(NEW.cogs_account_id, p.cogs_account_id, acct_role_account(NEW.tenant_id, NEW.entity_id, 'cogs'));
  END IF;
  IF NEW.is_purchased THEN
    NEW.expense_account_id := coalesce(NEW.expense_account_id, CASE WHEN NEW.item_type = 'inventory' THEN NEW.cogs_account_id END, p.expense_account_id, p.cogs_account_id,
                                       acct_role_account(NEW.tenant_id, NEW.entity_id, 'default_expense'));
  END IF;
  -- account type rules
  IF NEW.is_sold AND NEW.income_account_id IS NULL THEN RAISE EXCEPTION 'An item you sell needs an income account'; END IF;
  IF NEW.income_account_id IS NOT NULL THEN
    SELECT account_type INTO v_t FROM acct_chart_of_accounts WHERE id = NEW.income_account_id AND tenant_id = NEW.tenant_id;
    IF v_t IS NULL OR (v_t <> 'revenue' AND NOT (NEW.item_type IN ('gift_card') AND v_t = 'liability')) THEN
      RAISE EXCEPTION 'Income account must be an income (revenue) account%', CASE WHEN NEW.item_type='gift_card' THEN ' or the gift card liability' ELSE '' END; END IF;
  END IF;
  IF NEW.is_purchased THEN
    SELECT account_type INTO v_t FROM acct_chart_of_accounts WHERE id = NEW.expense_account_id AND tenant_id = NEW.tenant_id;
    IF v_t IS NULL OR v_t NOT IN ('expense','asset') THEN RAISE EXCEPTION 'Purchase account must be an expense, cost of goods sold, or asset account'; END IF;
  END IF;
  IF NEW.item_type = 'inventory' THEN
    SELECT account_type INTO v_t FROM acct_chart_of_accounts WHERE id = NEW.inventory_asset_account_id;
    IF v_t <> 'asset' THEN RAISE EXCEPTION 'Inventory asset account must be an asset'; END IF;
    SELECT account_type INTO v_t FROM acct_chart_of_accounts WHERE id = NEW.cogs_account_id;
    IF v_t <> 'expense' THEN RAISE EXCEPTION 'Cost of goods sold account must be an expense/COGS account'; END IF;
  END IF;
  IF NEW.item_type = 'bundle' AND (NEW.bundle_components IS NULL OR jsonb_array_length(NEW.bundle_components) = 0) THEN
    RAISE EXCEPTION 'A bundle needs at least one component item'; END IF;
  -- SKU: DEPT-SUB-SVC-LINE-0001 when not supplied
  IF NEW.sku IS NULL OR btrim(NEW.sku) = '' THEN
    NEW.sku := p.path_code || '-' || lpad(acct_next_seq(NEW.tenant_id, NEW.entity_id, 'sku:' || c.id)::text, 4, '0');
  END IF;
  NEW.sku := upper(btrim(NEW.sku));
  RETURN NEW;
END $$;

-- @seq 228
CREATE FUNCTION public.acct_item_class_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_item_classifications%ROWTYPE; v_expect text;
BEGIN
  NEW.code := upper(NEW.code);
  v_expect := CASE NEW.level WHEN 'sub_department' THEN 'department' WHEN 'service_type' THEN 'sub_department' WHEN 'sku_line' THEN 'service_type' END;
  IF NEW.level = 'department' THEN
    IF NEW.parent_id IS NOT NULL THEN RAISE EXCEPTION 'A department is the top level and has no parent'; END IF;
  ELSE
    SELECT * INTO p FROM acct_item_classifications WHERE id = NEW.parent_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'A % needs a parent %', NEW.level, v_expect; END IF;
    IF p.tenant_id <> NEW.tenant_id THEN RAISE EXCEPTION 'Parent belongs to another company'; END IF;
    IF p.level <> v_expect THEN RAISE EXCEPTION 'A % must sit under a % (got %)', NEW.level, v_expect, p.level; END IF;
    IF NOT p.is_active THEN RAISE EXCEPTION 'Parent % is inactive', p.name; END IF;
  END IF;
  RETURN NEW;
END $$;

-- @seq 229
CREATE FUNCTION public.acct_item_class_path(p_id uuid) RETURNS TABLE(path_code text, path_name text, department_id uuid, sub_department_id uuid, service_type_id uuid, sku_line_id uuid, income_account_id uuid, expense_account_id uuid, cogs_account_id uuid, asset_account_id uuid, tax_category text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH RECURSIVE c AS (
    SELECT x.*, 0 AS depth FROM acct_item_classifications x WHERE x.id = p_id
    UNION ALL SELECT y.*, c.depth + 1 FROM acct_item_classifications y JOIN c ON y.id = c.parent_id)
  SELECT string_agg(code, '-' ORDER BY depth DESC), string_agg(name, ' > ' ORDER BY depth DESC),
         max(id::text) FILTER (WHERE level='department')::uuid, max(id::text) FILTER (WHERE level='sub_department')::uuid,
         max(id::text) FILTER (WHERE level='service_type')::uuid, max(id::text) FILTER (WHERE level='sku_line')::uuid,
         (array_agg(default_income_account_id ORDER BY depth) FILTER (WHERE default_income_account_id IS NOT NULL))[1],
         (array_agg(default_expense_account_id ORDER BY depth) FILTER (WHERE default_expense_account_id IS NOT NULL))[1],
         (array_agg(default_cogs_account_id ORDER BY depth) FILTER (WHERE default_cogs_account_id IS NOT NULL))[1],
         (array_agg(default_asset_account_id ORDER BY depth) FILTER (WHERE default_asset_account_id IS NOT NULL))[1],
         (array_agg(default_tax_category ORDER BY depth) FILTER (WHERE default_tax_category IS NOT NULL))[1]
    FROM c;
$$;

-- @seq 230
CREATE FUNCTION public.acct_item_sync_commerce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.product_id IS NOT NULL THEN
    UPDATE products SET income_account_id = NEW.income_account_id, cogs_account_id = NEW.cogs_account_id
     WHERE id = NEW.product_id AND tenant_id = NEW.tenant_id
       AND (income_account_id IS DISTINCT FROM NEW.income_account_id OR cogs_account_id IS DISTINCT FROM NEW.cogs_account_id);
  END IF;
  IF NEW.catalog_item_id IS NOT NULL THEN
    UPDATE commerce_catalog_items SET taxable = NEW.taxable, sku = NEW.sku,
           metadata = metadata || jsonb_build_object('acct_item_id', NEW.id, 'tax_category', NEW.tax_category)
     WHERE id = NEW.catalog_item_id AND tenant_id = NEW.tenant_id;
  END IF;
  RETURN NEW;
END $$;

